"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["73928"],{21539(e){e.exports=JSON.parse('{"id":"FIN-1220","slug":"yield-curve-inversion","term":"Yield Curve Inversion","also_known_as":[],"difficulty":"Advanced","definition":"A yield curve inversion is when interest rates on short-term government bonds rise above those on long-term government bonds, reversing the usual pattern in which longer loans pay higher rates.","explanation":["Normally, investors demand higher yields for lending money for longer periods, so the yield curve slopes upwards. An inversion happens when short-term yields exceed long-term yields, often because central banks have raised short-term rates to fight inflation while investors expect slower growth and lower rates in future.","Common measures compare the yield on ten-year government bonds with two-year or three-month yields. For example, if the two-year yield is 4.8% and the ten-year yield is 4.2%, the curve is inverted.","Yield curve inversions have attracted attention because, in the United States, they have preceded most recessions in recent decades, often by around one to two years.","An inversion is a warning sign, not a guarantee. The timing between inversion and recession has varied, and some inversions have not been followed by recessions, as with the long US inversion that began in 2022. Factors such as central bank bond purchases can also affect long-term yields, making the signal harder to interpret."],"note":"","total":1500,"prev":{"slug":"yield-curve","term":"Yield Curve"},"next":{"slug":"yield-to-call","term":"Yield to Call"}}')}}]);